package com.supermarkettracker.infrastructure.persistence.adapter;
import com.supermarkettracker.domain.model.*; import com.supermarkettracker.domain.model.valueobject.Identificador; import com.supermarkettracker.domain.repository.ProdutoRepository; import com.supermarkettracker.infrastructure.persistence.mapper.ProdutoPersistenceMapper; import com.supermarkettracker.infrastructure.persistence.repository.ProdutoJpaRepository; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class ProdutoRepositoryJpaAdapter implements ProdutoRepository { private final ProdutoJpaRepository jpa; private final ProdutoPersistenceMapper mapper; public ProdutoRepositoryJpaAdapter(ProdutoJpaRepository jpa, ProdutoPersistenceMapper mapper){this.jpa=jpa;this.mapper=mapper;} public Produto salvar(Produto x){return mapper.toDomain(jpa.save(mapper.toEntity(x)));} public Optional<Produto> buscarPorId(Identificador id){return jpa.findById(id.valor()).map(mapper::toDomain);} public Optional<Produto> buscarPorCodigoBarras(Identificador empresaId,String codigo){return jpa.findByEmpresaIdAndCodigoBarras(empresaId.valor(),codigo).map(mapper::toDomain);} public List<Produto> buscarPorNome(Identificador empresaId,String nome){return jpa.buscarPorNome(empresaId.valor(),nome).stream().map(mapper::toDomain).toList();} public List<Produto> listarPorEmpresa(Identificador empresaId){return jpa.findByEmpresaIdOrderByNomeAsc(empresaId.valor()).stream().map(mapper::toDomain).toList();} public void excluirPorId(Identificador id){jpa.deleteById(id.valor());} }
